<?php

declare(strict_types=1);

namespace Saij\WpAppFramework\Manifest;

use RuntimeException;
use Saij\WpAppFramework\DependencyInjection\NoService;
use Saij\WpAppFramework\Hook\HookDefinition;
use Saij\WpAppFramework\Rest\RestRouteDefinition;

/**
 * Loads a manifest file generated by the build: plain data, interpreted by the
 * container and the hook and REST registrars without reflection.
 *
 * The manifest format is internal and may change between framework versions;
 * a manifest with a different format version must be rebuilt.
 *
 * @internal
 *
 * @phpstan-import-type HookArgument from HookDefinition
 * @phpstan-import-type RestArgument from RestRouteDefinition
 * @phpstan-import-type RestPermission from RestRouteDefinition
 * @phpstan-type HookEntry array{name: string, priority: int, acceptedArgs: int, filter: bool, class: class-string, method: string, arguments: list<HookArgument>}
 * @phpstan-type RouteEntry array{
 *     namespace: string,
 *     route: string,
 *     methods: list<string>,
 *     args: array<string, array<string, mixed>>,
 *     permission: RestPermission,
 *     class: class-string,
 *     method: string,
 *     arguments: list<RestArgument>,
 *     void: bool
 * }
 * @phpstan-type ManifestData array{
 *     format: int,
 *     candidates: list<class-string>,
 *     services: array<class-string, array<string, class-string>>,
 *     hooks: list<HookEntry>,
 *     routes: list<RouteEntry>
 * }
 */
#[NoService]
final class Manifest
{
    public const int FORMAT = 3;

    /**
     * @return ManifestData
     */
    public static function load(string $file): array
    {
        if (!is_file($file)) {
            throw new RuntimeException(sprintf('Manifest file %s does not exist.', $file));
        }

        $manifest = require $file;

        if (!is_array($manifest) || ($manifest['format'] ?? null) !== self::FORMAT) {
            throw new RuntimeException(sprintf(
                'Manifest file %s has an unsupported format (expected format %d). Rebuild the manifest with the installed framework version.',
                $file,
                self::FORMAT,
            ));
        }

        return $manifest;
    }
}
